# 2. 转换为 Pandas DataFrame
df_list = []
for algo, values in data_dict.items():
    for v in values:
        df_list.append({'Algorithm': algo, 'Ratio': v})
df = pd.DataFrame(df_list)

# 3. 绘图样式设置
plt.figure(figsize=(9, 7), dpi=120)
# 设置横坐标刻度（算法名）的字号
plt.xticks(fontsize=18)
# 顺便建议调大纵坐标刻度字号，保持比例协调
plt.yticks(fontsize=18)
sns.set_style("whitegrid", {'grid.linestyle': '--', 'grid.alpha': 0.6})

# 使用指定配色 (ColorBrewer Set2)
# 分别对应：青绿、珊瑚橙、淡紫、粉紫、草绿
set2_palette = {
    'PMC-MR': '#999999',
    'Swing': '#6A3D9A',
    'ZFP': '#A6CEE3',
    'SZ3': '#1F78B4',
    'Sim-Piece': '#FF7F00',
    'Mix-Piece': '#33A02C',
    'WARP': '#E31A1C'
}


# 4. 绘制箱线图
ax = sns.boxplot(x='Algorithm', y='Ratio', data=df,
                 hue='Algorithm',
                 palette=set2_palette,
                 legend=False,
                 width=0.4,          # 收窄箱体
                 linewidth=1.2,      # 轮廓粗细
                 showmeans=True,
                 # 均值标记：白色三角形，黑边
                 meanprops={"marker":"^", "markerfacecolor":"white", "markeredgecolor":"black", "markersize":"8"},
                 # 离群点标记：深灰色菱形
                 flierprops={"marker": "d", "markersize": 4, "markerfacecolor": "#555555", "markeredgecolor": "#555555", "alpha": 0.6})

# 5. 图像美化与对数坐标设置
plt.yscale('log') # 使用对数坐标，展示数据跨度
plt.title('Algorithm Compression compression time Analysis', fontsize=22, fontweight='bold', pad=20)
plt.ylabel('compression time', fontsize=22)
plt.xlabel('', fontsize=12)

# X轴标签角度微调
plt.xticks(rotation=45)

# 移除纵向网格线，使画面清爽
ax.xaxis.grid(False)

# 6. 自动调整布局并显示
plt.tight_layout()
plt.show()
